226	fn schema_fields(schema: &simd_json::OwnedValue) -> Vec<ProtoField> {
227	    let Ok(json_schema) = serde_json::to_value(schema) else {
228	        return vec![fallback_field("payload", "google.protobuf.Value", false)];
229	    };
230	
231	    let Some(properties) = json_schema.get("properties").and_then(|value| value.as_object()) else {
232	        return Vec::new();
233	    };
234	
235	    let mut fields = properties.iter().collect::<Vec<_>>();
236	    fields.sort_by_key(|(name, _)| *name);
237	
238	    fields
239	        .into_iter()
240	        .map(|(name, property)| {
241	            let (proto_type, repeated) = json_schema_type_to_proto(property);
242	            ProtoField {
243	                name: sanitize_proto_ident(name),
