263	fn json_schema_type_to_proto(schema: &serde_json::Value) -> (String, bool) {
264	    if schema
265	        .get("enum")
266	        .and_then(|value| value.as_array())
267	        .is_some_and(|values| !values.is_empty())
268	    {
269	        return ("string".to_string(), false);
270	    }
271	
272	    match schema.get("type") {
273	        Some(serde_json::Value::String(kind)) => match kind.as_str() {
274	            "string" => ("string".to_string(), false),
275	            "boolean" => ("bool".to_string(), false),
276	            "integer" => ("int64".to_string(), false),
277	            "number" => ("double".to_string(), false),
278	            "array" => {
279	                let item_type = schema
280	                    .get("items")
281	                    .map(|items| json_schema_type_to_proto(items).0)
282	                    .unwrap_or_else(|| "google.protobuf.Value".to_string());
283	                (item_type, true)
284	            }
285	            "object" => ("google.protobuf.Struct".to_string(), false),
286	            _ => ("google.protobuf.Value".to_string(), false),
287	        },
288	        Some(serde_json::Value::Array(kinds)) => {
289	            let first_non_null = kinds
290	                .iter()
291	                .filter_map(|value| value.as_str())
292	                .find(|kind| *kind != "null")
293	                .unwrap_or("object");
294	            json_schema_type_to_proto(&serde_json::json!({ "type": first_non_null }))
295	        }
296	        _ => {
297	            if schema.get("properties").is_some() {
298	                ("google.protobuf.Struct".to_string(), false)
299	            } else {
300	                ("google.protobuf.Value".to_string(), false)
301	            }
302	        }
303	    }
304	}
