308	        "string" => (field_descriptor_proto::Type::String, None),
309	        "bool" => (field_descriptor_proto::Type::Bool, None),
310	        "int64" => (field_descriptor_proto::Type::Int64, None),
311	        "double" => (field_descriptor_proto::Type::Double, None),
312	        "google.protobuf.Struct" => (
313	            field_descriptor_proto::Type::Message,
314	            Some(".google.protobuf.Struct".to_string()),
315	        ),
316	        "google.protobuf.Value" => (
317	            field_descriptor_proto::Type::Message,
318	            Some(".google.protobuf.Value".to_string()),
319	        ),
320	        _ => (
321	            field_descriptor_proto::Type::Message,
322	            Some(".google.protobuf.Value".to_string()),
323	        ),
324	    }
