327	/// Deterministic proto field numbers derived from schema property names.
328	///
329	/// Uses FNV-1a over the original JSON property name, folds into the valid
330	/// protobuf range, and skips the reserved 19000-19999 block.
331	pub fn stable_field_number(name: &str) -> i32 {
332	    const FNV_OFFSET: u32 = 0x811c9dc5;
333	    const FNV_PRIME: u32 = 0x01000193;
334	    const MAX_FIELD: u32 = 536_870_911;
335	    const RESERVED_START: u32 = 19_000;
336	    const RESERVED_END: u32 = 19_999;
337	
338	    let mut hash = FNV_OFFSET;
339	    for byte in name.as_bytes() {
340	        hash ^= u32::from(*byte);
341	        hash = hash.wrapping_mul(FNV_PRIME);
342	    }
343	
344	    let mut number = (hash % MAX_FIELD).max(1);
345	    if (RESERVED_START..=RESERVED_END).contains(&number) {
346	        number += RESERVED_END - RESERVED_START + 1;
347	    }
348	    number as i32
349	}
