mod tests {
    use super::*;
    use op_state_store::{MethodDecl, SideEffect};
    use prost::Message;
    use prost_types::FileDescriptorSet;

    pub(crate) fn demo_schema() -> PluginSchema {
        PluginSchema::builder("demo")
            .version("1.0.0")
            .method(MethodDecl {
                name: "GetState".to_string(),
                args: simd_json::json!({
