//! Sealed zero-copy blob container.
//!
//! ```text
//! offset  size  content
//! 0       8     magic "OPBLOB01"
//! 8       2     format version (u16 LE) = 1
//! 10      2     section count (u16 LE)
//! 12      4     reserved
//! 16      32    sha256 of the SCHEMA_JSON section (must equal schema_hash)
//! 48      16    reserved
//! 64      24*n  section table: tag u32, reserved u32, offset u64, len u64
//! ...           8-byte-aligned section payloads
//! ```
//!
//! Sections: 1 = canonical schema JSON, 2 = blob manifest JSON (the
//! `PluginObjectBlob` with the two byte payloads emptied), 3 = protobuf
//! `FileDescriptorSet`.
//!
//! `BlobRef` verifies magic + hash once, then hands out borrowed slices —
//! reads never copy or re-parse the payload sections. Sealing is
//! deterministic: same schema ⇒ same bytes ⇒ same hash, so the schema hash
//! doubles as the artifact identity in the filename.

use crate::blob::PluginObjectBlob;
use sha2::{Digest, Sha256};

pub const MAGIC: &[u8; 8] = b"OPBLOB01";
pub const FORMAT_VERSION: u16 = 1;

pub const SECTION_SCHEMA_JSON: u32 = 1;
pub const SECTION_MANIFEST_JSON: u32 = 2;
pub const SECTION_DESCRIPTOR_SET: u32 = 3;

const HEADER_LEN: usize = 64;
const SECTION_ENTRY_LEN: usize = 24;

/// Seal a blob into the immutable byte image.
pub fn seal(blob: &PluginObjectBlob) -> Vec<u8> {
    // Manifest carries everything except the two large byte payloads, which
    // get their own sections (and are refilled on read).
    let mut manifest = blob.clone();
    manifest.schema_json = Vec::new();
    manifest.grpc.descriptor_set = Vec::new();
    // Canonical key order for byte determinism.
    let manifest_value = serde_json::to_value(&manifest).expect("blob serializes");
    let manifest_json = serde_json::to_string(&sort_json(manifest_value)).expect("sorted json");

    let sections: [(u32, &[u8]); 3] = [
        (SECTION_SCHEMA_JSON, &blob.schema_json),
        (SECTION_MANIFEST_JSON, manifest_json.as_bytes()),
        (SECTION_DESCRIPTOR_SET, &blob.grpc.descriptor_set),
    ];

    let table_len = sections.len() * SECTION_ENTRY_LEN;
    let mut offset = align8(HEADER_LEN + table_len);
    let mut entries = Vec::with_capacity(sections.len());
    for (tag, bytes) in &sections {
        entries.push((*tag, offset as u64, bytes.len() as u64));
        offset = align8(offset + bytes.len());
    }

    let mut out = Vec::with_capacity(offset);
    out.extend_from_slice(MAGIC);
    out.extend_from_slice(&FORMAT_VERSION.to_le_bytes());
    out.extend_from_slice(&(sections.len() as u16).to_le_bytes());
    out.extend_from_slice(&[0u8; 4]);
    let mut h = Sha256::new();
    h.update(&blob.schema_json);
    out.extend_from_slice(&h.finalize());
    out.extend_from_slice(&[0u8; 16]);
    debug_assert_eq!(out.len(), HEADER_LEN);

    for (tag, off, len) in &entries {
        out.extend_from_slice(&tag.to_le_bytes());
        out.extend_from_slice(&[0u8; 4]);
        out.extend_from_slice(&off.to_le_bytes());
        out.extend_from_slice(&len.to_le_bytes());
    }
    for ((_, bytes), (_, off, _)) in sections.iter().zip(&entries) {
        while out.len() < *off as usize {
            out.push(0);
        }
        out.extend_from_slice(bytes);
    }
    out
}

fn sort_json(v: serde_json::Value) -> serde_json::Value {
    match v {
        serde_json::Value::Object(m) => {
            let sorted: serde_json::Map<String, serde_json::Value> =
                m.into_iter().map(|(k, v)| (k, sort_json(v))).collect();
            serde_json::Value::Object(sorted)
        }
        serde_json::Value::Array(a) => {
            serde_json::Value::Array(a.into_iter().map(sort_json).collect())
        }
        other => other,
    }
}

fn align8(n: usize) -> usize {
    (n + 7) & !7
}

/// Zero-copy view over sealed blob bytes. Construction verifies magic,
/// bounds, and the schema hash once; accessors return borrowed slices.
pub struct BlobRef<'a> {
    bytes: &'a [u8],
    sections: Vec<(u32, usize, usize)>,
}

impl<'a> BlobRef<'a> {
    pub fn new(bytes: &'a [u8]) -> Result<Self, String> {
        if bytes.len() < HEADER_LEN || &bytes[..8] != MAGIC {
            return Err("not an OPBLOB01 blob".into());
        }
        let version = u16::from_le_bytes([bytes[8], bytes[9]]);
        if version != FORMAT_VERSION {
            return Err(format!("unsupported blob format version {version}"));
        }
        let count = u16::from_le_bytes([bytes[10], bytes[11]]) as usize;
        let table_end = HEADER_LEN + count * SECTION_ENTRY_LEN;
        if bytes.len() < table_end {
            return Err("section table overruns blob".into());
        }
        let mut sections = Vec::with_capacity(count);
        for i in 0..count {
            let e = HEADER_LEN + i * SECTION_ENTRY_LEN;
            let tag = u32::from_le_bytes(bytes[e..e + 4].try_into().unwrap());
            let off = u64::from_le_bytes(bytes[e + 8..e + 16].try_into().unwrap()) as usize;
            let len = u64::from_le_bytes(bytes[e + 16..e + 24].try_into().unwrap()) as usize;
            if off + len > bytes.len() {
                return Err(format!("section {tag} overruns blob"));
            }
            sections.push((tag, off, len));
        }
        let blob = Self { bytes, sections };

        let schema = blob
            .section(SECTION_SCHEMA_JSON)
            .ok_or("missing schema section")?;
        let mut h = Sha256::new();
        h.update(schema);
        if h.finalize().as_slice() != &bytes[16..48] {
            return Err("schema hash mismatch: blob is corrupt or tampered".into());
        }
        Ok(blob)
    }

    fn section(&self, tag: u32) -> Option<&'a [u8]> {
        self.sections
            .iter()
            .find(|(t, _, _)| *t == tag)
            .map(|(_, off, len)| &self.bytes[*off..*off + *len])
    }

    /// Canonical `PluginSchema` JSON bytes — borrowed, zero-copy.
    pub fn schema_json(&self) -> &'a [u8] {
        self.section(SECTION_SCHEMA_JSON).unwrap_or(&[])
    }

    pub fn manifest_json(&self) -> &'a str {
        self.section(SECTION_MANIFEST_JSON)
            .and_then(|b| std::str::from_utf8(b).ok())
            .unwrap_or("")
    }

    /// Encoded `FileDescriptorSet` — borrowed, zero-copy; can be handed to
    /// reflection indexing without re-encoding.
    pub fn descriptor_set(&self) -> &'a [u8] {
        self.section(SECTION_DESCRIPTOR_SET).unwrap_or(&[])
    }

    pub fn schema_hash_hex(&self) -> String {
        hex::encode(&self.bytes[16..48])
    }

    /// Reconstruct the owned blob (the one intentional allocation on the
    /// read path).
    pub fn to_blob(&self) -> Result<PluginObjectBlob, String> {
        let mut blob: PluginObjectBlob = serde_json::from_str(self.manifest_json())
            .map_err(|e| format!("manifest parse: {e}"))?;
        blob.schema_json = self.schema_json().to_vec();
        blob.grpc.descriptor_set = self.descriptor_set().to_vec();
        if blob.schema_hash != self.schema_hash_hex() {
            return Err("manifest schema_hash disagrees with sealed header".into());
        }
        Ok(blob)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::blob::{blobify_plugin_schema, DbusObjectIdentity};
    use op_state_store::{MethodDecl, PluginSchema, SideEffect};

    fn demo_blob() -> PluginObjectBlob {
        let schema = PluginSchema::builder("demo")
            .version("1.0.0")
            .method(MethodDecl {
                name: "GetState".to_string(),
                args: simd_json::json!({"type":"object","properties":{"alpha":{"type":"string"}}}),
                returns: Some(simd_json::json!({"type":"object","properties":{"ok":{"type":"boolean"}}})),
                side_effect: SideEffect::Read,
                idempotent: true,
                required_capability: None,
                subid: "obs.service.demo.get-state@v1".to_string(),
            })
            .build();
        blobify_plugin_schema(
            "demo",
            schema,
            DbusObjectIdentity {
                bus_name: "org.opdbus.v1.plugins".to_string(),
                object_path: "/org/opdbus/v1/plugins/demo".to_string(),
                interface_name: "org.opdbus.v1.Plugin".to_string(),
            },
            "operation.plugin.v1",
            "operation.plugin.v1.DemoPluginMethods",
        )
    }

    #[test]
    fn seal_roundtrip_zero_copy_and_hash_guard() {
        let blob = demo_blob();
        let bytes = blob.seal();

        let r = BlobRef::new(&bytes).expect("valid blob");
        // Zero-copy: returned slices point inside the sealed image.
        let range = bytes.as_ptr() as usize..bytes.as_ptr() as usize + bytes.len();
        assert!(range.contains(&(r.schema_json().as_ptr() as usize)));
        assert!(range.contains(&(r.descriptor_set().as_ptr() as usize)));
        assert_eq!(r.schema_hash_hex(), blob.schema_hash);

        let round = r.to_blob().unwrap();
        assert_eq!(round.plugin_id, blob.plugin_id);
        assert_eq!(round.schema_json, blob.schema_json);
        assert_eq!(round.grpc.descriptor_set, blob.grpc.descriptor_set);
        assert_eq!(round.methods.len(), blob.methods.len());

        // Corruption is detected.
        let mut bad = bytes.clone();
        let pos = bad.len() - 8;
        bad[pos] ^= 0xff;
        // Either the schema section or a trailing section got flipped; the
        // schema-hash guard or manifest parse must reject it when the schema
        // bytes changed. Flip inside the schema section explicitly:
        let mut bad2 = bytes.clone();
        let schema_off = bad2
            .windows(6)
            .position(|w| w == b"\"demo\"")
            .expect("schema text");
        bad2[schema_off + 1] ^= 0x20;
        assert!(BlobRef::new(&bad2).is_err());
    }
}

